/* Phoenix Suns DNA — The valley: heat purple and blaze orange. */
.theme-phoenix-suns {
  --bg: oklch(0.205 0.070 294.4);
  --surface: oklch(0.240 0.091 293.8);
  --surface-2: oklch(0.276 0.109 292.9);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.555 0.182 294.7);
  --accent: oklch(0.649 0.180 42.3);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.603 0.159 299.5);
  --line: oklch(1 0 0 / 14%);
  --success: oklch(0.615 0.143 147.4);
  --warning: oklch(0.788 0.151 74.9);
  --danger: oklch(0.55 0.2 27);
  --radius: 0.375rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Big Shoulders", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0.01em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-phoenix-suns h1,
.theme-phoenix-suns h2,
.theme-phoenix-suns h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-phoenix-suns { --font-ui: var(--font-display); }
.theme-phoenix-suns h1, .theme-phoenix-suns h2 { text-transform: uppercase; font-weight: 800; }
.theme-phoenix-suns h1::after { content: ""; display: block; height: 5px; width: 6rem; margin-top: 0.6rem; background: linear-gradient(90deg, var(--accent) 0 50%, var(--accent-2) 50% 100%); }
.theme-phoenix-suns button { text-transform: uppercase; letter-spacing: 0.08em; font-weight: 700; }
.theme-phoenix-suns th { color: var(--accent); text-transform: uppercase; letter-spacing: 0.1em; font-size: 12px; }
.theme-phoenix-suns tbody tr:hover { background: color-mix(in oklab, var(--accent) 8%, transparent); }
.theme-phoenix-suns ::selection { background: var(--accent); color: var(--accent-fg); }
.theme-phoenix-suns { background-image: radial-gradient(ellipse at 50% 115%, oklch(0.6 0.18 45 / 30%), transparent 55%); } .theme-phoenix-suns h1 { background: linear-gradient(95deg, #e56020, #c04ba0); -webkit-background-clip: text; background-clip: text; color: transparent; }

/* alt mode: Association Edition white */
.theme-phoenix-suns.alt-mode {
  --bg: oklch(0.98 0.001 260); --surface: oklch(1 0 0); --surface-2: oklch(0.94 0.002 260);
  --fg: oklch(0.2 0.005 260); --fg-muted: oklch(0.45 0.005 260); --line: oklch(0.89 0.003 260);
  --accent: oklch(0.649 0.180 42.3); --accent-fg: oklch(1.000 0 0);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%); --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%); --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  background-image: none;
}
.theme-phoenix-suns.alt-mode h1 { background: none; -webkit-background-clip: initial; background-clip: initial; color: oklch(0.649 0.180 42.3); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
